import { Group, Mesh, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const userData = group.userData;

  // Optional material enhancement via color spec
  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const accentColor = colors.accent || '#ff2a38';
  const surfaceColor = colors.surface || '#0b0b10';

  // Load the GLB mesh asynchronously – group is returned immediately
  const loadPromise = ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;

    // Traverse to identify and optionally enhance materials
    scene.traverse((child) => {
      if (child.isMesh) {
        // Identify jewel-like meshes by name heuristics
        if (/jewel|gem|center|stone/i.test(child.name)) {
          const mat = new MeshStandardNodeMaterial();
          mat.color.set(accentColor);
          mat.emissive = mat.color.clone();
          mat.emissiveIntensity = 0.5;
          mat.metalness = 0;
          mat.roughness = 0.2;
          child.material = mat;
        }
        // For the machined rule, trust GLB materials – no override
      }
    });

    group.add(scene);
    userData._gltfScene = scene;
  }).catch((err) => {
    console.error('Failed to load divider GLB:', err);
  });

  // Interaction handlers (hover lift, press‑down on click, emit)
  userData.handlers = {
    pointerenter: () => {
      if (userData._originalY === undefined) {
        userData._originalY = group.position.y;
      }
      gsap.to(group.position, {
        y: userData._originalY + 0.15,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    pointerleave: () => {
      if (userData._originalY !== undefined) {
        gsap.to(group.position, {
          y: userData._originalY,
          duration: 0.3,
          ease: 'power2.out',
        });
      }
    },
    click: () => {
      // press-down effect
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.3,
            ease: 'power4.out',
          });
        },
      });
      ctx.emit('hub-home.select');
    },
  };

  // Cleanup resources and kill gsap tweens
  userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    if (userData._gltfScene) {
      userData._gltfScene.traverse((child) => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
      group.remove(userData._gltfScene);
    }
  };

  return group;
}
